OWNER_HTML=r'''<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>StokLedger Owner Admin</title><link rel="icon" href="/assets/stokledger-icon.png"><style>
:root{--navy:#0b2942;--blue:#0f6fa9;--teal:#0e8793;--green:#1c9b6c;--bg:#f4f7fa;--line:#dbe5ec;--text:#17324a;--muted:#6b7f8d;--danger:#b42318}*{box-sizing:border-box}body{margin:0;font-family:Segoe UI,Arial;background:var(--bg);color:var(--text)}button,input,select,textarea{font:inherit}.hidden{display:none!important}.login{min-height:100vh;display:grid;place-items:center;padding:20px;background:radial-gradient(circle at top left,#dff7f2,transparent 40%),linear-gradient(145deg,#eef6fb,#f9fbfc)}.login-card{width:min(460px,100%);background:#fff;border-radius:24px;padding:28px;box-shadow:0 25px 70px #17324a24}.brand{display:flex;align-items:center;gap:12px}.brand img{height:52px}.brand h1{font-size:22px;margin:0}.brand small{color:var(--muted)}.login-card input{width:100%;margin-top:18px;padding:13px;border:1px solid var(--line);border-radius:12px}.primary{background:var(--teal);color:#fff;border:0;border-radius:11px;padding:11px 15px;cursor:pointer}.secondary{background:#e9f1f5;color:var(--text);border:0;border-radius:11px;padding:11px 15px;cursor:pointer}.danger{background:var(--danger);color:#fff;border:0;border-radius:11px;padding:10px 13px;cursor:pointer}.login-card button{width:100%;margin-top:12px}.error{color:var(--danger)}.ok{color:#067647}.shell{display:grid;grid-template-columns:250px minmax(0,1fr);min-height:100vh}.side{background:linear-gradient(180deg,#082b4c,#0b2136);color:#fff;padding:20px 14px;position:sticky;top:0;height:100vh}.side .brand img{height:42px;background:#fff;border-radius:9px;padding:3px}.side nav{margin-top:26px;display:grid;gap:7px}.side nav button{background:transparent;color:#d9eaf3;border:0;text-align:left;padding:12px;border-radius:11px;cursor:pointer}.side nav button.active,.side nav button:hover{background:#15476c;color:#fff}.content{padding:22px}.topbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.topbar h2{margin:0}.cards{display:grid;grid-template-columns:repeat(4,minmax(160px,1fr));gap:12px;margin-bottom:18px}.stat{background:#fff;border:1px solid var(--line);border-radius:16px;padding:16px;box-shadow:0 5px 20px #17324a0b}.stat span{color:var(--muted);font-size:12px}.stat b{display:block;font-size:25px;margin-top:5px}.panel{background:#fff;border:1px solid var(--line);border-radius:18px;padding:18px;margin-bottom:18px;box-shadow:0 5px 20px #17324a0b}.toolbar{display:flex;gap:9px;flex-wrap:wrap;align-items:center;margin-bottom:12px}.toolbar input,.toolbar select{padding:10px 12px;border:1px solid var(--line);border-radius:10px;min-width:190px}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse;min-width:1000px}.table th,.table td{padding:10px;border-bottom:1px solid #edf1f4;text-align:left;font-size:13px}.table th{color:#587080;background:#f8fafb;position:sticky;top:0}.badge{display:inline-flex;padding:4px 8px;border-radius:999px;font-size:11px;font-weight:700;background:#edf2f5}.badge.active{background:#dff7e9;color:#12623e}.badge.trial{background:#e4f2ff;color:#0b5b91}.badge.expired{background:#fde7e5;color:#9d231a}.actions{display:flex;gap:5px;flex-wrap:wrap}.actions button{padding:7px 9px;font-size:12px}.grid{display:grid;grid-template-columns:repeat(3,minmax(180px,1fr));gap:12px}.field{display:flex;flex-direction:column;gap:5px}.field input,.field select,.field textarea{padding:10px;border:1px solid var(--line);border-radius:10px;width:100%}.field small{color:var(--muted)}dialog{border:0;border-radius:18px;padding:0;box-shadow:0 25px 80px #17324a38;width:min(720px,calc(100vw - 28px))}dialog::backdrop{background:#08182688}.modal{padding:20px}.modal-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.modal-head h3{margin:0}.modal-head button{border:0;background:#eef3f6;border-radius:50%;width:36px;height:36px;cursor:pointer}.price{background:#eaf7f7;border:1px solid #c8e4e6;padding:12px;border-radius:12px;margin-top:12px}.page{display:none}.page.active{display:block}@media(max-width:850px){.shell{display:block}.side{position:relative;height:auto}.side nav{grid-template-columns:repeat(3,1fr)}.content{padding:12px}.cards{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.topbar{align-items:flex-start}.topbar h2{font-size:19px}}@media(max-width:480px){.cards{grid-template-columns:1fr}.side nav{grid-template-columns:1fr 1fr}.toolbar input,.toolbar select{width:100%;min-width:0}}
</style></head><body>
<section id="ownerLoginView" class="login"><div class="login-card"><div class="brand"><img src="/assets/stokledger-icon.png"><div><h1>StokLedger Owner Admin</h1><small>Kontrol trial, langganan, user limit & promo</small></div></div><p style="color:#6b7f8d">Masukkan password Owner Admin yang disimpan di Railway.</p><input id="ownerPassword" type="password" placeholder="Password Owner Admin" autocomplete="current-password"><button class="primary" onclick="ownerLogin()">Masuk ke Admin</button><p id="loginMsg"></p><a href="/" style="color:#0e8793">← Kembali ke aplikasi</a></div></section>
<section id="ownerApp" class="shell hidden"><aside class="side"><div class="brand"><img src="/assets/stokledger-icon.png"><div><b>Owner Admin</b><small style="display:block;color:#c7deea">StokLedger Web</small></div></div><nav><button class="active" onclick="page('accounts',this)">◉ Akun & Trial</button><button onclick="page('discounts',this)">％ Kode Diskon</button><button onclick="loadAll()">↻ Refresh</button><button onclick="ownerLogout()">↪ Keluar</button></nav></aside><main class="content"><div class="topbar"><div><small style="color:#6b7f8d">OWNER CONSOLE</small><h2 id="pageTitle">Akun Trial & Langganan</h2></div><a href="/" class="secondary" style="text-decoration:none">Buka Aplikasi</a></div>
<div id="accounts" class="page active"><div class="cards"><div class="stat"><span>Total Akun</span><b id="stTotal">0</b></div><div class="stat"><span>Trial Aktif</span><b id="stTrial">0</b></div><div class="stat"><span>Langganan Aktif</span><b id="stActive">0</b></div><div class="stat"><span>Expired/Suspend</span><b id="stExpired">0</b></div></div><div class="panel"><div class="toolbar"><input id="aq" placeholder="Cari perusahaan / email / kode"><select id="astatus"><option value="">Semua status</option><option>TRIAL</option><option>ACTIVE</option><option>SUSPENDED</option></select><button class="primary" onclick="loadAccounts()">Cari</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Kode</th><th>Perusahaan / Email</th><th>Status</th><th>Sisa</th><th>Paket</th><th>User</th><th>Nilai</th><th>Aksi</th></tr></thead><tbody id="accountBody"></tbody></table></div></div></div>
<div id="discounts" class="page"><div class="panel"><h3>Buat / Update Kode Diskon</h3><div class="grid"><label class="field">Kode<input id="dcCode" placeholder="PROMO10"></label><label class="field">Tipe<select id="dcType"><option value="PERCENT">Persentase (%)</option><option value="FIXED">Nominal Rupiah</option></select></label><label class="field">Nilai<input id="dcValue" type="number" min="0"></label><label class="field">Berlaku Dari<input id="dcFrom" type="datetime-local"></label><label class="field">Berlaku Sampai<input id="dcUntil" type="datetime-local"></label><label class="field">Maks. Pemakaian<input id="dcMax" type="number" min="1" placeholder="Kosong = tanpa batas"></label><label class="field">Paket<select id="dcPlan"><option value="">Semua Paket</option><option value="HALF">6 Bulan</option><option value="YEAR">1 Tahun</option></select></label><label class="field">Status<select id="dcActive"><option value="1">Aktif</option><option value="0">Nonaktif</option></select></label><label class="field">Catatan<input id="dcNotes"></label></div><button class="primary" style="margin-top:12px" onclick="saveDiscount()">Simpan Kode Diskon</button><p id="dcMsg"></p></div><div class="panel"><div class="table-wrap"><table class="table" style="min-width:760px"><thead><tr><th>Kode</th><th>Diskon</th><th>Berlaku</th><th>Pakai</th><th>Paket</th><th>Status</th><th>Aksi</th></tr></thead><tbody id="discountBody"></tbody></table></div></div></div>
</main></section>
<dialog id="activateDialog"><div class="modal"><div class="modal-head"><h3>Aktivasi Langganan</h3><button onclick="activateDialog.close()">×</button></div><p id="actAccount" style="color:#6b7f8d"></p><input id="actId" type="hidden"><div class="grid"><label class="field">Paket<select id="actPlan" onchange="pricePreview()"><option value="HALF">6 Bulan · Rp1.200.000 / 2 user</option><option value="YEAR">1 Tahun · Rp2.000.000 / 2 user</option></select></label><label class="field">Add-on User<input id="actAddon" type="number" value="0" min="0" oninput="pricePreview()"></label><label class="field">Kode Diskon<input id="actDiscount" placeholder="Opsional"></label><label class="field">Tanggal Mulai<input id="actStart" type="date"></label><label class="field" style="grid-column:1/-1">Catatan<textarea id="actNotes"></textarea></label></div><div id="actPrice" class="price"></div><div style="display:flex;justify-content:flex-end;gap:8px;margin-top:14px"><button class="secondary" onclick="activateDialog.close()">Batal</button><button class="primary" onclick="activateAccount()">Aktifkan</button></div><p id="actMsg"></p></div></dialog>
<script>
let tok=localStorage.getItem('sl_owner_token')||'';const rup=n=>'Rp'+Number(n||0).toLocaleString('id-ID');
async function req(url,opt={}){opt.headers=Object.assign({'Content-Type':'application/json'},opt.headers||{});if(tok)opt.headers.Authorization='Bearer '+tok;let r=await fetch(url,opt);let x=await r.json().catch(()=>({}));if(!r.ok)throw new Error(x.error||('HTTP '+r.status));return x}
async function ownerLogin(){try{let x=await req('/api/owner/login',{method:'POST',body:JSON.stringify({password:ownerPassword.value})});tok=x.token;localStorage.setItem('sl_owner_token',tok);ownerLoginView.style.display='none';ownerApp.classList.remove('hidden');await loadAll()}catch(e){loginMsg.textContent=e.message;loginMsg.className='error'}}
function ownerLogout(){localStorage.removeItem('sl_owner_token');location.reload()}
function page(id,b){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');document.querySelectorAll('.side nav button').forEach(x=>x.classList.remove('active'));if(b)b.classList.add('active');pageTitle.textContent=id==='discounts'?'Kode Diskon Langganan':'Akun Trial & Langganan';if(id==='discounts')loadDiscounts();else loadAccounts()}
function badge(s){let c=s==='ACTIVE'?'active':s==='TRIAL'?'trial':'expired';return `<span class="badge ${c}">${s}</span>`}
async function loadAccounts(){try{let x=await req('/api/owner/accounts?q='+encodeURIComponent(aq.value||'')+'&status='+encodeURIComponent(astatus.value||''));let a=x.items||[];stTotal.textContent=a.length;stTrial.textContent=a.filter(x=>x.effective_status==='TRIAL').length;stActive.textContent=a.filter(x=>x.effective_status==='ACTIVE').length;stExpired.textContent=a.filter(x=>!['TRIAL','ACTIVE'].includes(x.effective_status)).length;accountBody.innerHTML=a.map(x=>`<tr><td><b>${x.account_code}</b></td><td><b>${esc(x.company_name)}</b><br><small>${esc(x.email)}</small></td><td>${badge(x.effective_status)}</td><td>${x.days_remaining} hari</td><td>${x.plan_code||'Trial 7 hari'}</td><td>${x.max_users}</td><td>${rup(x.amount)}</td><td><div class="actions"><button class="primary" onclick='openActivate(${JSON.stringify(x)})'>Aktivasi</button><button class="secondary" onclick="resetTrial(${x.id})">Trial 7 Hari</button><button class="${x.status==='SUSPENDED'?'primary':'danger'}" onclick="toggleStatus(${x.id},'${x.status==='SUSPENDED'?'TRIAL':'SUSPENDED'}')">${x.status==='SUSPENDED'?'Aktifkan':'Suspend'}</button></div></td></tr>`).join('')||'<tr><td colspan="8">Belum ada akun.</td></tr>'}catch(e){if(/401/.test(e.message))ownerLogout();else alert(e.message)}}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function openActivate(x){actId.value=x.id;actAccount.textContent=x.company_name+' · '+x.email;actAddon.value=x.addon_users||0;actStart.value=new Date().toISOString().slice(0,10);actDiscount.value='';actNotes.value=x.notes||'';pricePreview();activateDialog.showModal()}
function pricePreview(){let year=actPlan.value==='YEAR',base=year?2000000:1200000,addon=year?200000:100000,n=Math.max(0,Number(actAddon.value||0));actPrice.innerHTML=`Harga sebelum diskon: <b>${rup(base+n*addon)}</b> · Total user: <b>${2+n}</b><br><small>Diskon akan divalidasi saat aktivasi.</small>`}
async function activateAccount(){try{let x=await req('/api/owner/accounts/'+actId.value+'/activate',{method:'POST',body:JSON.stringify({plan_code:actPlan.value,addon_users:actAddon.value,discount_code:actDiscount.value,starts_at:actStart.value?actStart.value+'T00:00:00+07:00':null,notes:actNotes.value})});actMsg.textContent='Aktif sampai '+new Date(x.item.expires_at).toLocaleDateString('id-ID')+' · tagihan '+rup(x.item.amount);actMsg.className='ok';await loadAccounts();setTimeout(()=>activateDialog.close(),900)}catch(e){actMsg.textContent=e.message;actMsg.className='error'}}
async function resetTrial(id){if(!confirm('Reset trial akun ini menjadi 7 hari dari sekarang?'))return;try{await req('/api/owner/accounts/'+id+'/reset-trial',{method:'POST',body:'{}'});await loadAccounts()}catch(e){alert(e.message)}}
async function toggleStatus(id,status){if(!confirm('Ubah status akun menjadi '+status+'?'))return;try{await req('/api/owner/accounts/'+id+'/status',{method:'POST',body:JSON.stringify({status})});await loadAccounts()}catch(e){alert(e.message)}}
async function loadDiscounts(){try{let x=await req('/api/owner/discounts');discountBody.innerHTML=(x.items||[]).map(d=>`<tr><td><b>${d.code}</b></td><td>${d.discount_type==='PERCENT'?d.discount_value+'%':rup(d.discount_value)}</td><td>${d.valid_from||'-'}<br>${d.valid_until||'-'}</td><td>${d.used_count||0}${d.max_uses?'/'+d.max_uses:''}</td><td>${(JSON.parse(d.plans_json||'[]').join(', ')||'Semua')}</td><td>${d.is_active?'Aktif':'Nonaktif'}</td><td><button class="danger" onclick="deleteDiscount('${d.code}')">Hapus</button></td></tr>`).join('')||'<tr><td colspan="7">Belum ada kode diskon.</td></tr>'}catch(e){alert(e.message)}}
async function saveDiscount(){try{await req('/api/owner/discounts',{method:'POST',body:JSON.stringify({code:dcCode.value,discount_type:dcType.value,discount_value:dcValue.value,valid_from:dcFrom.value?new Date(dcFrom.value).toISOString():null,valid_until:dcUntil.value?new Date(dcUntil.value).toISOString():null,max_uses:dcMax.value||null,plans:dcPlan.value?[dcPlan.value]:[],is_active:dcActive.value==='1',notes:dcNotes.value})});dcMsg.textContent='Kode diskon tersimpan.';dcMsg.className='ok';await loadDiscounts()}catch(e){dcMsg.textContent=e.message;dcMsg.className='error'}}
async function deleteDiscount(code){if(!confirm('Hapus kode '+code+'?'))return;try{await req('/api/owner/discounts/'+encodeURIComponent(code),{method:'DELETE'});await loadDiscounts()}catch(e){alert(e.message)}}
async function loadAll(){await Promise.all([loadAccounts(),loadDiscounts()])}
if(tok){ownerLoginView.style.display='none';ownerApp.classList.remove('hidden');loadAll().catch(()=>ownerLogout())}
</script></body></html>'''
